import java.util.*;
public class Main {
  static int n,best=Integer.MAX_VALUE;static int[][] a;static boolean[] used;
  static void dfs(int d,int sum){
    if(sum>=best)return;
    if(d==n){best=sum;return;}
    for(int j=0;j<n;j++)if(!used[j]){
      used[j]=true;dfs(d+1,sum+a[d][j]);used[j]=false;
    }
  }
  public static void main(String[] args){
    Scanner s=new Scanner(System.in);n=s.nextInt();a=new int[n][n];used=new boolean[n];
    for(int i=0;i<n;i++)for(int j=0;j<n;j++)a[i][j]=s.nextInt();
    dfs(0,0);System.out.println(best);
  }
}
