import java.util.*;
public class Main {
  public static void main(String[] args){
    Scanner s=new Scanner(System.in);int R=s.nextInt(),C=s.nextInt(),r=0,c=0,d=3;char[][] g=new char[R][];
    for(int i=0;i<R;i++){g[i]=s.next().toCharArray();for(int j=0;j<C;j++)if(g[i][j]=='S'){r=i;c=j;g[i][j]='.';}}
    int[] dr={-1,1,0,0},dc={0,0,-1,1};String dirs="UDLR";
    for(char ch:s.next().toCharArray()){
      if(ch=='F'){
        int nr=r+dr[d],nc=c+dc[d];
        while(nr>=0&&nr<R&&nc>=0&&nc<C){
          if(g[nr][nc]=='#')break;
          if(g[nr][nc]=='*'){g[nr][nc]='.';break;}
          nr+=dr[d];nc+=dc[d];
        }
      }else{
        d=dirs.indexOf(ch);int nr=r+dr[d],nc=c+dc[d];
        if(nr>=0&&nr<R&&nc>=0&&nc<C&&g[nr][nc]=='.'){r=nr;c=nc;}
      }
    }
    int count=0;for(char[] row:g)for(char ch:row)if(ch=='*')count++;
    System.out.println(r+" "+c+" "+count);
  }
}
