import java.util.*;
public class Main {
  public static void main(String[] args){
    Scanner s=new Scanner(System.in);int n=s.nextInt();List<int[]> live=new ArrayList<>();
    for(int i=0;i<n;i++)live.add(new int[]{s.nextInt()*2,s.nextInt()*2,s.nextInt(),s.nextInt()});
    int[] dx={0,0,-1,1},dy={1,-1,0,0};int total=0;
    for(int step=1;step<=80&&!live.isEmpty();step++){
      Map<String,List<int[]>> groups=new HashMap<>();
      for(int[] a:live){
        a[0]+=dx[a[2]];a[1]+=dy[a[2]];
        if(Math.abs(a[0])>40||Math.abs(a[1])>40)continue;
        groups.computeIfAbsent(a[0]+":"+a[1],k->new ArrayList<>()).add(a);
      }
      live=new ArrayList<>();
      for(List<int[]> group:groups.values()){
        if(group.size()==1)live.add(group.get(0));else for(int[] a:group)total+=a[3];
      }
    }
    System.out.println(total);
  }
}
